<template><div class="page"><div class="page-head"><div><h1 class="page-title">预约管理</h1><div class="page-sub">查看预约队列、到书通知和失效情况</div></div></div><div class="toolbar"><el-radio-group v-model="filter"><el-radio-button label="全部" value=""/><el-radio-button label="等待中" value="WAITING"/><el-radio-button label="已取消" value="CANCELLED"/></el-radio-group></div><el-card class="table-card"><el-table :data="shown"><el-table-column prop="id" label="预约编号"/><el-table-column prop="readerId" label="读者ID"/><el-table-column prop="bookId" label="图书ID"/><el-table-column prop="queueNo" label="排队序号"><template #default="{row}"><b>第 {{row.queueNo}} 位</b></template></el-table-column><el-table-column prop="reserveTime" label="预约时间"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status==='WAITING'?'warning':'info'">{{row.status==='WAITING'?'等待中':'已取消'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='WAITING'" link type="danger" @click="cancel(row.id)">取消预约</el-button></template></el-table-column></el-table></el-card></div></template><script setup lang="ts">import{ref,computed,onMounted}from'vue';import api from'../api';import{ElMessage}from'element-plus';const rows=ref<any[]>([]),filter=ref(''),shown=computed(()=>filter.value?rows.value.filter(x=>x.status===filter.value):rows.value);onMounted(load);async function load(){rows.value=await api.get('/api/reservations')}async function cancel(id:number){await api.delete(`/api/reservations/${id}`);ElMessage.success('预约已取消');load()}</script>

